export const routes={home:'',individuals:'individuals',approach:'approach',assessment:'assessment',organisations:'organisations',workshop:'workshops/stress-and-burnout',learn:'learn',science:'science',stress:'learn/stress-and-recovery',burnout:'learn/burnout-at-work',brain:'learn/brain-health',courses:'courses',social:'social',about:'about',faq:'faq',contact:'contact',privacy:'privacy',legal:'legal',roadmap:'roadmap'};
